const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Init Run" } });

// Reset per-run counters at the START — workflow static data persists across
// executions; a run that crashed before Code: Build Summary must not carry
// stale counts into the next run.
const staticData = $getWorkflowStaticData('global');
staticData.checked = 0;
staticData.deleted_orphan_mailbox = 0;
staticData.deleted_orphan_message = 0;
staticData.thumbnail_files_removed = 0;
staticData.redis_hashes_cleaned = 0;
staticData.skipped_ok = 0;
staticData.skipped_mailbox_unreachable = 0;
staticData.skipped_mailbox_empty = 0;
staticData.skipped_mailbox_syncing = 0;
staticData._plan = null;

// Which trigger fired? Read the trigger nodes by NAME — n8n throws for a node
// that did not execute in this run. Do NOT read $input.first() here: the
// upstream lock node returns a fresh object without body/query (PROJ-92 bug).
let firedNode = null;
try { if ($('Schedule Trigger: Monthly').first()) firedNode = 'schedule'; } catch(e) {}
try { if (!firedNode && $('Webhook: POST /alice-mail-reconcile').first()) firedNode = 'webhook'; } catch(e) {}
const fromSchedule = firedNode === 'schedule';

let body = {}, query = {};
if (!fromSchedule) {
  try {
    const webhookItem = $('Webhook: POST /alice-mail-reconcile').first().json;
    body = webhookItem.body || {};
    query = webhookItem.query || {};
  } catch(e) {}
}

let trigger, mode, maxRuntimeSeconds;
if (fromSchedule) {
  trigger = 'schedule';
  mode = 'confirm';           // schedule always executes — no schedule dry-run
  maxRuntimeSeconds = 3600;   // fixed 1h window
} else {
  trigger = 'webhook';
  const confirmRaw = body.confirm !== undefined ? body.confirm : query.confirm;
  mode = (confirmRaw === true || confirmRaw === 'true') ? 'confirm' : 'dry-run';
  const rawLimit = body.time_limit_seconds !== undefined ? body.time_limit_seconds : query.time_limit_seconds;
  const parsed = parseInt(rawLimit, 10);
  maxRuntimeSeconds = (!isNaN(parsed) && parsed > 0) ? parsed : null;
}

logger.info(`[mail-reconcile] Init: trigger=${trigger} mode=${mode} max_runtime_seconds=${maxRuntimeSeconds === null ? 'none' : maxRuntimeSeconds}`);
return [{ json: { trigger, mode, max_runtime_seconds: maxRuntimeSeconds, window_start: Date.now() } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Acquire Lock" } });
const redis = require('redis');
const crypto = require('crypto');
// Same lock key as alice-dms-processor / PROJ-97 reconcile / the DMS backfills.
const LOCK_KEY = 'alice:dms:processor:lock:run';
const LOCK_TTL_MS = 3900000; // 65 min — TTL fallback (>= the 3600s schedule window)

const run = $input.first().json;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
const ownerToken = crypto.randomUUID();
let acquired = false;
let redisReachable = false;
try {
  await client.connect();
  redisReachable = true;
  const res = await client.set(LOCK_KEY, JSON.stringify({ owner: ownerToken, workflow: 'alice-mail-reconcile', started_at: new Date().toISOString() }), { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
} catch(e) {
  logger.info('[mail-reconcile] Lock acquire error: ' + e.message + ' — failing closed (skip run)');
  acquired = false;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { ...run, _lock_acquired: acquired, _redis_reachable: redisReachable, lock_owner: acquired ? ownerToken : null } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Respond Locked" } });
const run = $input.first().json;
const reason = run._redis_reachable ? 'lock alice:dms:processor:lock:run is already held' : 'Redis unreachable — failing closed';
logger.info(`[mail-reconcile] Run skipped: ${reason}`);
return [{ json: { status: 'skipped', mode: run.mode, trigger: run.trigger, stopped_reason: 'locked', message: 'Lauf bereits aktiv oder Redis nicht erreichbar', checked: 0, deleted_orphan_mailbox: 0, deleted_orphan_message: 0, thumbnail_files_removed: 0, redis_hashes_cleaned: 0, skipped_ok: 0, skipped_mailbox_unreachable: 0, skipped_mailbox_empty: 0, skipped_mailbox_syncing: 0, mailboxes_checked: 0, remaining: null } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Query Weaviate" } });
const axios = require('axios');
const run = $('Code: Init Run').first().json;
const WEAVIATE = 'http://weaviate:8080';
const LIMIT = 100;

// Flat work list of ALL Email objects. thumbnail_path / fileHash are queried
// with a graceful fallback if the field is not on the class (Muster PROJ-95).
let includeThumb = true;
let includeHash = true;
function isMissingFieldError(errors, field) {
  try { const s = JSON.stringify(errors); return s.includes('Cannot query field') && s.includes(field); } catch(e) { return false; }
}

const work = [];
let cursor = null;
while (true) {
  const cursorClause = cursor ? `, after: \"${cursor}\"` : '';
  const hashClause = includeHash ? ' fileHash' : '';
  const thumbClause = includeThumb ? ' thumbnail_path' : '';
  const gql = `{ Get { Email(limit: ${LIMIT}${cursorClause}) { _additional { id creationTimeUnix } mailboxId imapUid subject date${hashClause}${thumbClause} } } }`;
  let results;
  try {
    const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
    if (r.data?.errors) {
      if (includeThumb && isMissingFieldError(r.data.errors, 'thumbnail_path')) { includeThumb = false; continue; }
      if (includeHash && isMissingFieldError(r.data.errors, 'fileHash')) { includeHash = false; continue; }
      logger.warn(`[mail-reconcile] GraphQL error for Email: ${JSON.stringify(r.data.errors)}`);
      break;
    }
    results = r.data?.data?.Get?.Email || [];
  } catch(e) {
    logger.warn(`[mail-reconcile] Weaviate request failed: ${e.message}`);
    // Weaviate unreachable — cannot build the work list. Abort the run (the
    // lock is released by the error branch is NOT triggered here; return a
    // sentinel that Code: Plan Run turns into a clean 'skipped').
    return [{ json: { _weaviate_error: true, trigger: run.trigger, mode: run.mode, max_runtime_seconds: run.max_runtime_seconds, window_start: run.window_start, lock_owner: $('Code: Acquire Lock').first().json.lock_owner } }];
  }
  if (results.length === 0) break;
  for (const doc of results) {
    work.push({
      weaviate_uuid: doc._additional?.id || null,
      creation_time_unix: doc._additional?.creationTimeUnix ? Number(doc._additional.creationTimeUnix) : null,
      mailbox_id: doc.mailboxId || null,
      imap_uid: (doc.imapUid !== undefined && doc.imapUid !== null && doc.imapUid !== '') ? String(doc.imapUid) : null,
      subject: doc.subject || '',
      date: doc.date || null,
      file_hash: doc.fileHash || null,
      thumbnail_path: doc.thumbnail_path || null
    });
  }
  if (results.length < LIMIT) break;
  cursor = results[results.length - 1]?._additional?.id;
  if (!cursor) break;
}

const total = work.length;
logger.info(`[mail-reconcile] Email objects to check: ${total}`);
const common = { _empty: total === 0, _weaviate_error: false, total_objects: total, trigger: run.trigger, mode: run.mode, max_runtime_seconds: run.max_runtime_seconds, window_start: run.window_start, lock_owner: $('Code: Acquire Lock').first().json.lock_owner };
if (total === 0) return [{ json: { ...common } }];
return work.map(w => ({ json: { ...w, ...common } }));

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Plan Run" } });
const axios = require('axios');
const MAIL_READER = 'http://alice-mail-reader:8007';
const SYNC_TIMEOUT_MIN = 30; // matches alice-mail-sync PG: Check Active Syncs

const items = $input.all();
const first = items[0].json;

function setAbortPlan(reason) {
  const sd = $getWorkflowStaticData('global');
  sd._plan = {
    abort: true, abort_reason: reason, total_objects: 0,
    trigger: first.trigger, mode: first.mode,
    max_runtime_seconds: first.max_runtime_seconds || null,
    window_start: first.window_start || Date.now(),
    lock_owner: first.lock_owner || null,
    live_mailbox_ids: [], snapshots: {}, mailboxes_checked: 0
  };
}

// --- abort paths from Code: Query Weaviate ---
if (first._weaviate_error) {
  logger.warn('[mail-reconcile] Weaviate unreachable — aborting run, nothing deleted');
  setAbortPlan('weaviate_unreachable');
  return [{ json: { _abort: true, _empty: true } }];
}

// --- load the mailbox rows ---
const mailboxRows = $('PG: Load Mailboxes').all().map(i => i.json).filter(r => r && r.id);
const liveMailboxIds = new Set(mailboxRows.map(r => String(r.id)));

// --- per-mailbox snapshot: which mailboxes have >= 1 Email object? ---
const work = first._empty ? [] : items.map(i => i.json);
const mailboxesWithObjects = new Set();
for (const w of work) {
  if (w.mailbox_id && liveMailboxIds.has(String(w.mailbox_id))) mailboxesWithObjects.add(String(w.mailbox_id));
}

// snapshot per mailbox id: { state: 'ok'|'unreachable'|'empty'|'syncing', uidSet: Set, query_ts: <ms> }
const snapshots = {};
let mailboxesChecked = 0;

for (const row of mailboxRows) {
  const mid = String(row.id);
  if (!mailboxesWithObjects.has(mid)) continue; // no Email object references it — skip the IMAP roundtrip

  // syncing check — status='syncing' AND updated_at within the timeout window
  const isSyncing = String(row.status || '') === 'syncing' &&
    row.updated_at && ((Date.now() - new Date(row.updated_at).getTime()) / 60000) < SYNC_TIMEOUT_MIN;
  if (isSyncing) {
    snapshots[mid] = { state: 'syncing' };
    logger.warn(`[mail-reconcile] Mailbox ${mid} is syncing — skipped this run`);
    continue;
  }

  // one list-uids roundtrip
  const query_ts = Date.now();
  try {
    const r = await axios.post(`${MAIL_READER}/list-uids`, {
      host: row.imap_host,
      port: row.imap_port,
      ssl: row.ssl_enabled,
      username: row.imap_username,
      password_enc: row.password_enc,
      folder: 'INBOX'
    }, { timeout: 60000, validateStatus: () => true });

    if (r.status < 200 || r.status >= 300) {
      snapshots[mid] = { state: 'unreachable' };
      logger.warn(`[mail-reconcile] list-uids failed for mailbox ${mid}: HTTP ${r.status} ${r.data?.error || ''} — mailbox skipped`);
      continue;
    }
    const uids = Array.isArray(r.data?.uids) ? r.data.uids.map(u => String(u)) : [];
    if (uids.length === 0) {
      snapshots[mid] = { state: 'empty' };
      logger.warn(`[mail-reconcile] list-uids returned 0 UIDs for mailbox ${mid} — mailbox skipped (skipped_mailbox_empty)`);
      continue;
    }
    snapshots[mid] = { state: 'ok', uidSet: uids, query_ts };
    mailboxesChecked++;
    logger.info(`[mail-reconcile] Mailbox ${mid}: ${uids.length} live INBOX UIDs`);
  } catch(e) {
    snapshots[mid] = { state: 'unreachable' };
    logger.warn(`[mail-reconcile] list-uids error for mailbox ${mid}: ${e.message} — mailbox skipped`);
  }
}

// Fail-safe: PG returned ZERO mailbox rows. Ambiguous — a genuinely emptied
// table vs. a query that silently returned nothing. Deleting the ENTIRE Email
// collection as \"mailbox orphans\" on that basis is exactly the irreversible
// mistake the spec's fail-safe asymmetry forbids. Only proceed with case (a)
// wholesale deletion when there is truly nothing to lose (0 Email objects too);
// otherwise abort the run untouched.
if (mailboxRows.length === 0 && work.length > 0) {
  logger.warn(`[mail-reconcile] PG: Load Mailboxes returned 0 rows but ${work.length} Email objects exist — aborting run (fail-safe, nothing deleted)`);
  setAbortPlan('no_mailbox_rows');
  return [{ json: { _abort: true, _empty: true } }];
}

logger.info(`[mail-reconcile] Plan: ${mailboxRows.length} mailboxes, ${mailboxesWithObjects.size} referenced, ${mailboxesChecked} with a live UID list`);

// The run context + per-mailbox snapshots live on staticData ONCE — do NOT
// spread the (potentially huge) uid sets onto every work item (Muster PROJ-97).
// Code: Process Object / Time Check / Build Summary read them from here.
const staticData = $getWorkflowStaticData('global');
staticData._plan = {
  abort: false,
  total_objects: work.length,
  trigger: first.trigger,
  mode: first.mode,
  max_runtime_seconds: first.max_runtime_seconds,
  window_start: first.window_start,
  lock_owner: first.lock_owner,
  live_mailbox_ids: [...liveMailboxIds],
  snapshots,
  mailboxes_checked: mailboxesChecked
};

if (work.length === 0) return [{ json: { _abort: false, _empty: true } }];
// Lean per-object items only.
return work.map(w => ({ json: { ...w, _abort: false, _empty: false } }));

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Process Object" } });
const axios = require('axios');
const redis = require('redis');

const item = $input.first().json;
const plan = $getWorkflowStaticData('global')._plan || {};
const WEAVIATE = 'http://weaviate:8080';
const THUMBNAILER = 'http://alice-dms-thumbnailer:8004';
const mode = plan.mode;                 // 'dry-run' | 'confirm'
const confirm = mode === 'confirm';
const liveMailboxIds = new Set(plan.live_mailbox_ids || []);
const snapshots = plan.snapshots || {};
const SHA256_RE = /^[a-f0-9]{64}$/i;

const staticData = $getWorkflowStaticData('global');
staticData.checked = (staticData.checked || 0) + 1;
function bump(k, n) { staticData[k] = (staticData[k] || 0) + (n === undefined ? 1 : n); }

const uuid = item.weaviate_uuid;
const mailboxId = item.mailbox_id ? String(item.mailbox_id) : null;
const imapUid = item.imap_uid;   // already normalised to String|null in Code: Query Weaviate
const subject = item.subject || '';
const fileHash = item.file_hash || null;
const hashValid = !!fileHash && SHA256_RE.test(String(fileHash));

// ---- classify ----
// 1. mailboxId empty OR not in the live set     -> orphan_mailbox
// 2. mailbox snapshot syncing/unreachable/empty -> keep (skipped_mailbox_*)
// 3. imapUid missing (pre-PROJ-46-BUG-2 legacy) -> keep (skipped_ok)
// 4. object newer than the list-uids query time -> keep (skipped_ok, race guard)
// 5. String(imapUid) in the snapshot uidSet     -> healthy (skipped_ok)
// 6. otherwise                                  -> orphan_message
let category = 'healthy';

if (!uuid) {
  logger.warn('[mail-reconcile] Email object without uuid — skipping');
  bump('skipped_ok');
  return [{ json: { _category: 'healthy' } }];
}

if (!mailboxId || !liveMailboxIds.has(mailboxId)) {
  category = 'orphan_mailbox';
} else {
  const snap = snapshots[mailboxId];
  if (!snap || snap.state !== 'ok') {
    if (snap && snap.state === 'unreachable') bump('skipped_mailbox_unreachable');
    else if (snap && snap.state === 'empty') bump('skipped_mailbox_empty');
    else if (snap && snap.state === 'syncing') bump('skipped_mailbox_syncing');
    else bump('skipped_ok');
    return [{ json: { _category: 'keep' } }];
  }
  if (!imapUid) {
    logger.warn(`[mail-reconcile] Email ${uuid} has no imapUid (legacy) — keeping (skipped_ok)`);
    bump('skipped_ok');
    return [{ json: { _category: 'keep' } }];
  }
  // race guard: object created after the snapshot was taken
  const objTsMs = item.creation_time_unix ? Number(item.creation_time_unix)
    : (item.date ? new Date(item.date).getTime() : null);
  if (objTsMs && snap.query_ts && objTsMs > snap.query_ts) {
    logger.warn(`[mail-reconcile] Email ${uuid} is newer than the list-uids snapshot — keeping (race guard)`);
    bump('skipped_ok');
    return [{ json: { _category: 'keep' } }];
  }
  const uidSet = new Set(snap.uidSet || []);
  if (uidSet.has(String(imapUid))) {
    bump('skipped_ok');
    return [{ json: { _category: 'healthy' } }];
  }
  category = 'orphan_message';
}

// ---- orphan (a or b) ----
logger.info(`[mail-reconcile] ${category} uuid=${uuid} mailboxId=${mailboxId || '(none)'} imapUid=${imapUid || '(none)'} subject=${JSON.stringify(subject).slice(0,120)} — ${confirm ? 'deleting' : 'DRY-RUN would delete'}`);
const counterKey = category === 'orphan_mailbox' ? 'deleted_orphan_mailbox' : 'deleted_orphan_message';
bump(counterKey); // planned-or-done

if (!confirm) {
  return [{ json: { _category: category } }];
}

// 1) thumbnail file (idempotent, never blocks the object delete)
try {
  const tr = await axios.delete(`${THUMBNAILER}/thumbnail/${uuid}`, { timeout: 10000, validateStatus: () => true });
  if (tr.status >= 200 && tr.status < 300 && tr.data?.deleted) bump('thumbnail_files_removed');
} catch(e) {
  logger.warn(`[mail-reconcile] thumbnail delete call failed for ${uuid}: ${e.message}`);
}

// 2) delete the Weaviate object
try {
  await axios.delete(`${WEAVIATE}/v1/objects/Email/${uuid}`, { timeout: 10000 });
} catch(e) {
  logger.warn(`[mail-reconcile] DELETE Email/${uuid} failed: ${e.message}`);
  bump(counterKey, -1);
  bump('skipped_ok');
  return [{ json: { _category: category } }];
}

// 3) Redis fileHash cleanup — only for archived .eml objects, and only if no
// other live Weaviate object (any collection) still uses the hash.
if (hashValid) {
  let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
  const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
  try {
    await client.connect();
    // is the hash still referenced by a live object?
    let stillUsed = false;
    const COLLECTIONS = ['Invoice', 'BankStatement', 'Document', 'SecuritySettlement', 'Contract', 'Email'];
    for (const c of COLLECTIONS) {
      const q = `{ Aggregate { ${c}(where: { path: [\"fileHash\"], operator: Equal, valueText: \"${fileHash}\" }) { meta { count } } } }`;
      try {
        const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: q }, { headers: { 'Content-Type': 'application/json' }, timeout: 10000 });
        const cnt = r.data?.data?.Aggregate?.[c]?.[0]?.meta?.count;
        if (typeof cnt === 'number' && cnt > 0) { stillUsed = true; break; }
      } catch(e) { /* treat as unknown -> err on not-cleaning below */ stillUsed = true; break; }
    }
    if (!stillUsed) {
      const members = await client.sMembers(`alice:dms:hash_to_paths:${fileHash}`);
      for (const m of members) await client.hDel('alice:dms:path_to_hash', m);
      await client.del(`alice:dms:hash_to_paths:${fileHash}`);
      await client.sRem('alice:dms:processed', fileHash);
      bump('redis_hashes_cleaned');
      logger.info(`[mail-reconcile] cleaned Redis map entries for hash ${fileHash}`);
    }
  } catch(e) {
    logger.warn(`[mail-reconcile] Redis cleanup failed for hash ${fileHash}: ${e.message}`);
  } finally {
    await client.quit().catch(() => {});
  }
}

return [{ json: { _category: category } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Time Check" } });
// Runs once per object. Reads the window from staticData._plan.
const plan = $getWorkflowStaticData('global')._plan || {};
const maxRuntime = plan.max_runtime_seconds;
let timeLimitReached = false;
if (maxRuntime !== null && maxRuntime !== undefined) {
  const elapsed = (Date.now() - plan.window_start) / 1000;
  timeLimitReached = elapsed >= maxRuntime;
  if (timeLimitReached) {
    logger.info(`[mail-reconcile] Time limit reached (elapsed=${Math.round(elapsed)}s, limit=${maxRuntime}s) — leaving loop`);
  }
}
return [{ json: { _time_limit_reached: timeLimitReached } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Build Summary" } });
const redis = require('redis');
const staticData = $getWorkflowStaticData('global');
const plan = staticData._plan || {};

const checked = staticData.checked || 0;
const deleted_orphan_mailbox = staticData.deleted_orphan_mailbox || 0;
const deleted_orphan_message = staticData.deleted_orphan_message || 0;
const thumbnail_files_removed = staticData.thumbnail_files_removed || 0;
const redis_hashes_cleaned = staticData.redis_hashes_cleaned || 0;
const skipped_ok = staticData.skipped_ok || 0;
const skipped_mailbox_unreachable = staticData.skipped_mailbox_unreachable || 0;
const skipped_mailbox_empty = staticData.skipped_mailbox_empty || 0;
const skipped_mailbox_syncing = staticData.skipped_mailbox_syncing || 0;

// reset for the next run (also reset in Code: Init Run — belt and braces)
staticData.checked = 0;
staticData.deleted_orphan_mailbox = 0;
staticData.deleted_orphan_message = 0;
staticData.thumbnail_files_removed = 0;
staticData.redis_hashes_cleaned = 0;
staticData.skipped_ok = 0;
staticData.skipped_mailbox_unreachable = 0;
staticData.skipped_mailbox_empty = 0;
staticData.skipped_mailbox_syncing = 0;

const abort = plan.abort === true;
// _plan stays until the next run's Code: Init Run nulls it — Build Summary may
// still need lock_owner below; clearing it here would race the release.

const totalObjects = plan.total_objects || 0;
const stoppedByTime = (() => {
  if (abort) return false;
  if (plan.max_runtime_seconds === null || plan.max_runtime_seconds === undefined) return false;
  return ((Date.now() - plan.window_start) / 1000) >= plan.max_runtime_seconds;
})();
const remaining = stoppedByTime ? Math.max(0, totalObjects - checked) : 0;
const stopped_reason = abort ? 'locked' : (stoppedByTime ? 'time_limit' : 'completed');

// release the lock (owner-checked) on every completion path
const owner = plan.lock_owner;
if (owner) {
  const RELEASE = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
  let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
  const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
  try {
    await client.connect();
    await client.eval(RELEASE, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] });
  } catch(e) {
    logger.info(`[mail-reconcile] Lock release error: ${e.message}`);
  } finally {
    await client.quit().catch(() => {});
  }
}

const summary = {
  status: abort ? 'skipped' : 'ok',
  mode: plan.mode,
  trigger: plan.trigger,
  stopped_reason,
  checked,
  deleted_orphan_mailbox,
  deleted_orphan_message,
  thumbnail_files_removed,
  redis_hashes_cleaned,
  skipped_ok,
  skipped_mailbox_unreachable,
  skipped_mailbox_empty,
  skipped_mailbox_syncing,
  mailboxes_checked: plan.mailboxes_checked || 0,
  remaining
};
logger.info(`[mail-reconcile] Summary: ${JSON.stringify(summary)}`);
return [{ json: summary }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-mail-reconcile", node: "Code: Release Lock (error)" } });
const redis = require('redis');
const errorData = $input.first().json;

// Best-effort lock release on crash. Owner token is gone here, so drop the
// lock only if it is ours by workflow tag — otherwise leave it for the TTL.
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
  const raw = await client.get('alice:dms:processor:lock:run');
  if (raw) {
    let data = null;
    try { data = JSON.parse(raw); } catch(e) {}
    if (data && data.workflow === 'alice-mail-reconcile') {
      await client.del('alice:dms:processor:lock:run');
      logger.info('[mail-reconcile] Released stale lock after error');
    }
  }
} catch(e) {
  logger.info('[mail-reconcile] Lock release on error failed: ' + e.message + ' (TTL will clear it)');
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { workflow: 'alice-mail-reconcile', error: errorData.execution?.error?.message || 'Unknown error', node: errorData.execution?.lastNodeExecuted || 'unknown', timestamp: new Date().toISOString(), execution_id: errorData.execution?.id || null } }];
